#!/bin/zsh
# compile-kit-shaders.sh - kit toolchain for the multiview shaders.
#
# HLSL (SV_ViewID, Shader Model 6.1) -> SPIR-V with DXC directly (SDL_shadercross compiles with a
# fixed vs_6_0 profile and rejects SV_ViewID, so it cannot be used for this step) -> MSL and JSON
# with shadercross (SPIRV-Cross, SDL bindings) -> vertex MSL rewritten to [[amplification_id]]
# with msl-amplification.sh.
# The generated files live in the repository (Kit/shaders/Compiled/, outside the synchronized
# Xcode folder so that Xcode does not collect them as resources) and additionally as C strings in
# kit_shaders_generated.h so that neither the CLI nor the app needs to load files. No hand-written MSL.
#
# Usage: Kit/sdl-gpu-kit/tools/compile-kit-shaders.sh
# Environment: SHADERCROSS_BUILD_DIR, DXC, SHADERCROSS (paths), default: build under ThirdParty/SDL_shadercross/build.

set -euo pipefail

KIT="${0:A:h:h}"
ROOT="${KIT:h:h}"
TOOLS="${SHADERCROSS_BUILD_DIR:-$ROOT/ThirdParty/SDL_shadercross/build}"
DXC="${DXC:-$TOOLS/external/DirectXShaderCompiler/bin/dxc}"
SHADERCROSS="${SHADERCROSS:-$TOOLS/shadercross}"
AMPLIFY="$KIT/tools/msl-amplification.sh"
SRC="$KIT/../shaders"
OUT="$SRC/Compiled"
HEADER="$KIT/kit_shaders_generated.h"

[[ -x "$DXC" ]] || { echo "ERROR: dxc missing: $DXC" >&2; exit 1; }
[[ -x "$SHADERCROSS" ]] || { echo "ERROR: shadercross missing: $SHADERCROSS" >&2; exit 1; }
mkdir -p "$OUT"

# Same flags as SDL_shadercross (src/SDL_shadercross.c:443-451), only the shader model is 6.1.
DXC_FLAGS=(-spirv -fspv-flatten-resource-arrays -fspv-preserve-interface)
quiet() { "$@" 2>&1 | sed -E 's/^[0-9-]+ [0-9:.]+ shadercross\[[0-9:]+\] //' | grep -v "^$" || true; }

compile() {
    local name="$1" stage="$2" profile="$3"
    local base="$OUT/$name.$stage"
    echo "== $name $stage"
    "$DXC" -T "$profile" -E "${stage}_main" "${DXC_FLAGS[@]}" "$SRC/$name.hlsl" -Fo "$base.spv"
    quiet "$SHADERCROSS" "$base.spv" -e "${stage}_main" -t "$stage" -s SPIRV -o "$base.msl"
    quiet "$SHADERCROSS" "$base.spv" -e "${stage}_main" -t "$stage" -s SPIRV -o "$base.json"
    if [[ "$stage" == "vertex" ]]; then
        "$AMPLIFY" "$base.msl" "$base.amp.msl" | head -1
        mv "$base.amp.msl" "$base.msl"
        grep -n "amplification_id\|gl_ViewIndex" "$base.msl" | head -3
    fi
    echo "   $(wc -c < "$base.msl") bytes MSL, reflection: $(cat "$base.json")"
}

compile multiview vertex vs_6_1
compile multiview fragment ps_6_1

echo "== Check: Metal compiler for xros and macOS"
for stage in vertex fragment; do
    xcrun -sdk xros metal -x metal -c "$OUT/multiview.$stage.msl" -o "$OUT/multiview.$stage.xros.air"
    xcrun -sdk macosx metal -x metal -c "$OUT/multiview.$stage.msl" -o "$OUT/multiview.$stage.macos.air"
    rm -f "$OUT/multiview.$stage.xros.air" "$OUT/multiview.$stage.macos.air"
done
echo "   both stages compile for xros and macOS"

echo "== C header $HEADER"
python3 - "$HEADER" "$OUT/multiview.vertex.msl" "$OUT/multiview.fragment.msl" <<'EOF'
import sys, json
header, vert, frag = sys.argv[1:4]
def literal(path):
    text = open(path, encoding="utf-8").read()
    lines = []
    for line in text.split("\n"):
        escaped = line.replace("\\", "\\\\").replace('"', '\\"')
        lines.append('    "' + escaped + '\\n"')
    return "\n".join(lines)
with open(header, "w", encoding="utf-8") as f:
    f.write("/* kit_shaders_generated.h - generated by tools/compile-kit-shaders.sh, do not edit by hand.\n")
    f.write(" * Source: shaders/multiview.hlsl; path: DXC (SM 6.1) -> SPIRV-Cross -> msl-amplification.sh. */\n")
    f.write("#ifndef KIT_SHADERS_GENERATED_H\n#define KIT_SHADERS_GENERATED_H\n\n")
    f.write("static const char kit_multiview_vertex_msl[] =\n" + literal(vert) + ";\n\n")
    f.write("static const char kit_multiview_fragment_msl[] =\n" + literal(frag) + ";\n\n")
    f.write("#endif /* KIT_SHADERS_GENERATED_H */\n")
print("   written")
EOF
ls -la "$OUT" "$HEADER" | grep -v "^total"
